package com.example.plannerdiario.ui.components

import android.content.Context
import android.net.Uri
import android.provider.OpenableColumns
import androidx.activity.compose.rememberLauncherForActivityResult
import androidx.activity.result.contract.ActivityResultContracts
import androidx.compose.foundation.BorderStroke
import androidx.compose.foundation.background
import androidx.compose.foundation.border
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.foundation.verticalScroll
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.filled.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.draw.drawBehind
import androidx.compose.ui.geometry.CornerRadius
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.graphicsLayer
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.style.TextOverflow
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import androidx.compose.ui.window.Dialog
import com.example.plannerdiario.ui.theme.*

@Composable
fun AddTaskDialog(
    onDismiss: () -> Unit,
    onConfirm: (
        title: String,
        description: String,
        attachUri: String?,
        attachType: String?,
        attachName: String?
    ) -> Unit
) {
    val context = LocalContext.current
    var title       by remember { mutableStateOf("") }
    var description by remember { mutableStateOf("") }
    var titleError  by remember { mutableStateOf(false) }
    var attachType  by remember { mutableStateOf<String?>(null) }
    var attachUri   by remember { mutableStateOf<String?>(null) }
    var attachName  by remember { mutableStateOf<String?>(null) }
    var linkUrl     by remember { mutableStateOf("") }

    val pdfLauncher = rememberLauncherForActivityResult(
        ActivityResultContracts.OpenDocument()
    ) { uri ->
        uri?.let {
            grantPersistablePermission(context, it)
            attachUri  = it.toString()
            attachType = "PDF"
            attachName = getFileName(context, it)
            linkUrl    = ""
        }
    }
    val imageLauncher = rememberLauncherForActivityResult(
        ActivityResultContracts.OpenDocument()
    ) { uri ->
        uri?.let {
            grantPersistablePermission(context, it)
            attachUri  = it.toString()
            attachType = "IMAGE"
            attachName = getFileName(context, it)
            linkUrl    = ""
        }
    }

    // ── Shared TextField colors ───────────────────────────────────────────
    @Composable
    fun styledTextFieldColors() = TextFieldDefaults.colors(
        focusedContainerColor   = Cream,
        unfocusedContainerColor = Cream,
        errorContainerColor     = Cream,
        focusedIndicatorColor   = Color.Transparent,
        unfocusedIndicatorColor = Color.Transparent,
        errorIndicatorColor     = Color.Transparent,
        focusedTextColor        = DarkInk,
        unfocusedTextColor      = DarkInk,
        errorTextColor          = DarkInk
    )

    Dialog(onDismissRequest = onDismiss) {
        // Outer box – lets the shadow overflow without being clipped
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .graphicsLayer { clip = false }
                .drawBehind {
                    drawRoundRect(
                        color        = DarkInk,
                        topLeft      = Offset(5.dp.toPx(), 5.dp.toPx()),
                        size         = size,
                        cornerRadius = CornerRadius(16.dp.toPx())
                    )
                }
        ) {
            Surface(
                shape  = RoundedCornerShape(16.dp),
                color  = Cream,
                border = BorderStroke(2.dp, DarkInk),
                modifier = Modifier.fillMaxWidth()
            ) {
                Column(
                    modifier = Modifier
                        .padding(horizontal = 20.dp, vertical = 18.dp)
                        .verticalScroll(rememberScrollState()),
                    verticalArrangement = Arrangement.spacedBy(14.dp)
                ) {

                    // ── Title row ─────────────────────────────────────────
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text         = "NOVA TAREFA",
                            style        = MaterialTheme.typography.labelLarge,
                            fontWeight   = FontWeight.ExtraBold,
                            letterSpacing = 2.sp,
                            color        = PinkVivid
                        )
                        Box(
                            modifier = Modifier
                                .size(32.dp)
                                .border(1.5.dp, DarkInk, RoundedCornerShape(6.dp))
                                .clip(RoundedCornerShape(6.dp))
                                .clickable { onDismiss() },
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                Icons.Default.Close, "Fechar",
                                modifier = Modifier.size(18.dp),
                                tint     = DarkInk
                            )
                        }
                    }

                    // ── Título da tarefa ───────────────────────────────────
                    val titleBorder = if (titleError) Color(0xFFE53935) else PinkVivid
                    TextField(
                        value         = title,
                        onValueChange = { title = it; titleError = false },
                        placeholder   = {
                            Text(
                                "Título da tarefa...",
                                color = DarkInk.copy(alpha = 0.38f),
                                style = MaterialTheme.typography.bodyMedium
                            )
                        },
                        singleLine = true,
                        modifier   = Modifier
                            .fillMaxWidth()
                            .border(2.dp, titleBorder, RoundedCornerShape(8.dp)),
                        shape  = RoundedCornerShape(8.dp),
                        colors = styledTextFieldColors()
                    )
                    if (titleError) {
                        Text(
                            "Título obrigatório",
                            color = Color(0xFFE53935),
                            style = MaterialTheme.typography.labelSmall,
                            modifier = Modifier.offset(y = (-8).dp)
                        )
                    }

                    // ── Descrição ──────────────────────────────────────────
                    TextField(
                        value         = description,
                        onValueChange = { description = it },
                        placeholder   = {
                            Text(
                                "Descrição (opcional)...",
                                color = DarkInk.copy(alpha = 0.38f),
                                style = MaterialTheme.typography.bodyMedium
                            )
                        },
                        minLines = 2,
                        maxLines = 4,
                        modifier = Modifier
                            .fillMaxWidth()
                            .border(2.dp, PinkVivid.copy(alpha = 0.4f), RoundedCornerShape(8.dp)),
                        shape  = RoundedCornerShape(8.dp),
                        colors = styledTextFieldColors()
                    )

                    // ── Anexo ──────────────────────────────────────────────
                    Text(
                        "Anexo (opcional)",
                        style      = MaterialTheme.typography.labelLarge,
                        fontWeight = FontWeight.Bold,
                        color      = DarkInk.copy(alpha = 0.6f),
                        letterSpacing = 0.5.sp
                    )
                    Row(
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        TaskAttachButton(
                            icon     = Icons.Default.PictureAsPdf,
                            label    = "PDF",
                            selected = attachType == "PDF",
                            modifier = Modifier.weight(1f),
                            onClick  = { pdfLauncher.launch(arrayOf("application/pdf")) }
                        )
                        TaskAttachButton(
                            icon     = Icons.Default.Image,
                            label    = "Imagem",
                            selected = attachType == "IMAGE",
                            modifier = Modifier.weight(1f),
                            onClick  = { imageLauncher.launch(arrayOf("image/*")) }
                        )
                        TaskAttachButton(
                            icon     = Icons.Default.Link,
                            label    = "Link",
                            selected = attachType == "LINK",
                            modifier = Modifier.weight(1f),
                            onClick  = { attachType = "LINK"; attachUri = null; attachName = null }
                        )
                    }

                    // Chip do arquivo selecionado
                    if (attachType in listOf("PDF", "IMAGE") && attachUri != null) {
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .border(1.5.dp, DarkInk.copy(alpha = 0.3f), RoundedCornerShape(8.dp))
                                .clip(RoundedCornerShape(8.dp))
                                .background(PinkVivid.copy(alpha = 0.08f))
                                .padding(horizontal = 12.dp, vertical = 8.dp)
                        ) {
                            Row(
                                verticalAlignment   = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                Icon(
                                    if (attachType == "PDF") Icons.Default.PictureAsPdf
                                    else Icons.Default.Image,
                                    contentDescription = null,
                                    modifier = Modifier.size(18.dp),
                                    tint     = PinkVivid
                                )
                                Text(
                                    text     = attachName ?: "arquivo",
                                    style    = MaterialTheme.typography.bodySmall,
                                    color    = DarkInk,
                                    modifier = Modifier.weight(1f),
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis
                                )
                                Box(
                                    modifier = Modifier
                                        .size(20.dp)
                                        .clip(RoundedCornerShape(4.dp))
                                        .clickable {
                                            attachType = null
                                            attachUri  = null
                                            attachName = null
                                        },
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        Icons.Default.Close, "Remover",
                                        modifier = Modifier.size(14.dp),
                                        tint     = DarkInk.copy(alpha = 0.6f)
                                    )
                                }
                            }
                        }
                    }

                    // Campo de link
                    if (attachType == "LINK") {
                        TextField(
                            value         = linkUrl,
                            onValueChange = { linkUrl = it },
                            placeholder   = {
                                Text(
                                    "URL (https://...)",
                                    color = DarkInk.copy(alpha = 0.38f),
                                    style = MaterialTheme.typography.bodyMedium
                                )
                            },
                            leadingIcon = {
                                Icon(Icons.Default.Link, null,
                                    modifier = Modifier.size(18.dp), tint = PinkVivid)
                            },
                            trailingIcon = if (linkUrl.isNotEmpty()) ({
                                Box(
                                    modifier = Modifier
                                        .size(24.dp)
                                        .clip(RoundedCornerShape(4.dp))
                                        .clickable { attachType = null; linkUrl = "" },
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(Icons.Default.Close, "Limpar",
                                        modifier = Modifier.size(16.dp),
                                        tint = DarkInk.copy(alpha = 0.6f))
                                }
                            }) else null,
                            singleLine = true,
                            modifier   = Modifier
                                .fillMaxWidth()
                                .border(2.dp, PinkVivid.copy(alpha = 0.5f), RoundedCornerShape(8.dp)),
                            shape  = RoundedCornerShape(8.dp),
                            colors = styledTextFieldColors()
                        )
                    }

                    // ── Botão Adicionar ────────────────────────────────────
                    val active = title.isNotBlank()
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .graphicsLayer { clip = false }
                            .drawBehind {
                                drawRoundRect(
                                    color        = DarkInk.copy(alpha = if (active) 1f else 0.4f),
                                    topLeft      = Offset(4.dp.toPx(), 4.dp.toPx()),
                                    size         = size,
                                    cornerRadius = CornerRadius(8.dp.toPx())
                                )
                            }
                    ) {
                        Button(
                            onClick = {
                                if (title.isBlank()) { titleError = true; return@Button }
                                val finalUri = when (attachType) {
                                    "LINK" -> linkUrl.trim().ifBlank { null }
                                    else   -> attachUri
                                }
                                val finalName = when (attachType) {
                                    "LINK" -> linkUrl.trim().ifBlank { null }
                                    else   -> attachName
                                }
                                onConfirm(
                                    title.trim(), description.trim(),
                                    finalUri, if (finalUri != null) attachType else null,
                                    finalName
                                )
                            },
                            modifier = Modifier.fillMaxWidth(),
                            shape    = RoundedCornerShape(8.dp),
                            enabled  = active,
                            border   = BorderStroke(2.dp, DarkInk.copy(alpha = if (active) 1f else 0.4f)),
                            colors   = ButtonDefaults.buttonColors(
                                containerColor         = PinkVivid,
                                disabledContainerColor = PinkVivid.copy(alpha = 0.5f)
                            ),
                            contentPadding = PaddingValues(vertical = 14.dp)
                        ) {
                            Text(
                                "Adicionar",
                                fontWeight    = FontWeight.ExtraBold,
                                color         = Color.White,
                                letterSpacing = 1.sp
                            )
                        }
                    }
                }
            }
        }
    }
}

// ── Botão de anexo estilizado ─────────────────────────────────────────────────
@Composable
private fun TaskAttachButton(
    icon: ImageVector,
    label: String,
    selected: Boolean,
    modifier: Modifier = Modifier,
    onClick: () -> Unit
) {
    Box(
        modifier = modifier
            .graphicsLayer { clip = false }
            .drawBehind {
                if (selected) {
                    drawRoundRect(
                        color        = DarkInk,
                        topLeft      = Offset(3.dp.toPx(), 3.dp.toPx()),
                        size         = size,
                        cornerRadius = CornerRadius(8.dp.toPx())
                    )
                }
            }
    ) {
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .border(
                    width  = if (selected) 2.dp else 1.5.dp,
                    color  = if (selected) DarkInk else DarkInk.copy(alpha = 0.25f),
                    shape  = RoundedCornerShape(8.dp)
                )
                .clip(RoundedCornerShape(8.dp))
                .background(if (selected) PinkVivid else Cream)
                .clickable { onClick() }
                .padding(vertical = 8.dp),
            contentAlignment = Alignment.Center
        ) {
            Column(
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(3.dp)
            ) {
                Icon(
                    icon, null,
                    modifier = Modifier.size(18.dp),
                    tint     = if (selected) Color.White else DarkInk.copy(alpha = 0.6f)
                )
                Text(
                    label,
                    style      = MaterialTheme.typography.labelSmall,
                    fontWeight = if (selected) FontWeight.Bold else FontWeight.Normal,
                    color      = if (selected) Color.White else DarkInk.copy(alpha = 0.6f)
                )
            }
        }
    }
}

// ── Helpers ───────────────────────────────────────────────────────────────────
private fun grantPersistablePermission(context: Context, uri: Uri) {
    try {
        context.contentResolver.takePersistableUriPermission(
            uri, android.content.Intent.FLAG_GRANT_READ_URI_PERMISSION
        )
    } catch (_: Exception) {}
}

private fun getFileName(context: Context, uri: Uri): String {
    var result: String? = null
    if (uri.scheme == "content") {
        context.contentResolver.query(uri, null, null, null, null)?.use { cursor ->
            if (cursor.moveToFirst()) {
                val idx = cursor.getColumnIndex(OpenableColumns.DISPLAY_NAME)
                if (idx >= 0) result = cursor.getString(idx)
            }
        }
    }
    return result ?: uri.lastPathSegment ?: "arquivo"
}

package com.example.plannerdiario.ui.components

import android.content.Context
import android.net.Uri
import android.provider.OpenableColumns
import androidx.activity.compose.rememberLauncherForActivityResult
import androidx.activity.result.contract.ActivityResultContracts
import androidx.compose.foundation.BorderStroke
import androidx.compose.foundation.background
import androidx.compose.foundation.border
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.foundation.verticalScroll
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.filled.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.draw.drawBehind
import androidx.compose.ui.geometry.CornerRadius
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.graphicsLayer
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.style.TextOverflow
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import androidx.compose.ui.window.Dialog
import com.example.plannerdiario.ui.theme.*

@Composable
fun AddTaskDialog(    onDismiss: () -> Unit,
    onConfirm: (
        title: String,
        description: String,
        attachUri: String?,
        attachType: String?,
        attachName: String?
    ) -> Unit
) {
    val context = LocalContext.current
    var title       by remember { mutableStateOf("") }
    var description by remember { mutableStateOf("") }
    var titleError  by remember { mutableStateOf(false) }
    var attachType  by remember { mutableStateOf<String?>(null) }
    var attachUri   by remember { mutableStateOf<String?>(null) }
    var attachName  by remember { mutableStateOf<String?>(null) }
    var linkUrl     by remember { mutableStateOf("") }

    val pdfLauncher = rememberLauncherForActivityResult(
        ActivityResultContracts.OpenDocument()
    ) { uri ->
        uri?.let {
            grantPersistablePermission(context, it)
            attachUri  = it.toString()
            attachType = "PDF"
            attachName = getFileName(context, it)
            linkUrl    = ""
        }
    }
    val imageLauncher = rememberLauncherForActivityResult(
        ActivityResultContracts.OpenDocument()
    ) { uri ->
        uri?.let {
            grantPersistablePermission(context, it)
            attachUri  = it.toString()
            attachType = "IMAGE"
            attachName = getFileName(context, it)
            linkUrl    = ""
        }
    }

    // ── Shared TextField colors ───────────────────────────────────────────
    @Composable
    fun styledTextFieldColors() = TextFieldDefaults.colors(
        focusedContainerColor   = Cream,
        unfocusedContainerColor = Cream,
        errorContainerColor     = Cream,
        focusedIndicatorColor   = Color.Transparent,
        unfocusedIndicatorColor = Color.Transparent,
        errorIndicatorColor     = Color.Transparent,
        focusedTextColor        = DarkInk,
        unfocusedTextColor      = DarkInk,
        errorTextColor          = DarkInk
    )

    Dialog(onDismissRequest = onDismiss) {
        // Outer box – lets the shadow overflow without being clipped
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .graphicsLayer { clip = false }
                .drawBehind {
                    drawRoundRect(
                        color        = DarkInk,
                        topLeft      = Offset(5.dp.toPx(), 5.dp.toPx()),
                        size         = size,
                        cornerRadius = CornerRadius(16.dp.toPx())
                    )
                }
        ) {
            Surface(
                shape  = RoundedCornerShape(16.dp),
                color  = Cream,
                border = BorderStroke(2.dp, DarkInk),
                modifier = Modifier.fillMaxWidth()
            ) {
                Column(
                    modifier = Modifier
                        .padding(horizontal = 20.dp, vertical = 18.dp)
                        .verticalScroll(rememberScrollState()),
                    verticalArrangement = Arrangement.spacedBy(14.dp)
                ) {

                    // ── Title row ─────────────────────────────────────────
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text         = "NOVA TAREFA",
                            style        = MaterialTheme.typography.labelLarge,
                            fontWeight   = FontWeight.ExtraBold,
                            letterSpacing = 2.sp,
                            color        = PinkVivid
                        )
                        Box(
                            modifier = Modifier
                                .size(32.dp)
                                .border(1.5.dp, DarkInk, RoundedCornerShape(6.dp))
                                .clip(RoundedCornerShape(6.dp))
                                .clickable { onDismiss() },
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                Icons.Default.Close, "Fechar",
                                modifier = Modifier.size(18.dp),
                                tint     = DarkInk
                            )
                        }
                    }

                    // ── Título da tarefa ───────────────────────────────────
                    val titleBorder = if (titleError) Color(0xFFE53935) else PinkVivid
                    TextField(
                        value         = title,
                        onValueChange = { title = it; titleError = false },
                        placeholder   = {
                            Text(
                                "Título da tarefa...",
                                color = DarkInk.copy(alpha = 0.38f),
                                style = MaterialTheme.typography.bodyMedium
                            )
                        },
                        singleLine = true,
                        modifier   = Modifier
                            .fillMaxWidth()
                            .border(2.dp, titleBorder, RoundedCornerShape(8.dp)),
                        shape  = RoundedCornerShape(8.dp),
                        colors = styledTextFieldColors()
                    )
                    if (titleError) {
                        Text(
                            "Título obrigatório",
                            color = Color(0xFFE53935),
                            style = MaterialTheme.typography.labelSmall,
                            modifier = Modifier.offset(y = (-8).dp)
                        )
                    }

                    // ── Descrição ──────────────────────────────────────────
                    TextField(
                        value         = description,
                        onValueChange = { description = it },
                        placeholder   = {
                            Text(
                                "Descrição (opcional)...",
                                color = DarkInk.copy(alpha = 0.38f),
                                style = MaterialTheme.typography.bodyMedium
                            )
                        },
                        minLines = 2,
                        maxLines = 4,
                        modifier = Modifier
                            .fillMaxWidth()
                            .border(2.dp, PinkVivid.copy(alpha = 0.4f), RoundedCornerShape(8.dp)),
                        shape  = RoundedCornerShape(8.dp),
                        colors = styledTextFieldColors()
                    )

                    // ── Anexo ──────────────────────────────────────────────
                    Text(
                        "Anexo (opcional)",
                        style      = MaterialTheme.typography.labelLarge,
                        fontWeight = FontWeight.Bold,
                        color      = DarkInk.copy(alpha = 0.6f),
                        letterSpacing = 0.5.sp
                    )
                    Row(
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        TaskAttachButton(
                            icon     = Icons.Default.PictureAsPdf,
                            label    = "PDF",
                            selected = attachType == "PDF",
                            modifier = Modifier.weight(1f),
                            onClick  = { pdfLauncher.launch(arrayOf("application/pdf")) }
                        )
                        TaskAttachButton(
                            icon     = Icons.Default.Image,
                            label    = "Imagem",
                            selected = attachType == "IMAGE",
                            modifier = Modifier.weight(1f),
                            onClick  = { imageLauncher.launch(arrayOf("image/*")) }
                        )
                        TaskAttachButton(
                            icon     = Icons.Default.Link,
                            label    = "Link",
                            selected = attachType == "LINK",
                            modifier = Modifier.weight(1f),
                            onClick  = { attachType = "LINK"; attachUri = null; attachName = null }
                        )
                    }

                    // Chip do arquivo selecionado
                    if (attachType in listOf("PDF", "IMAGE") && attachUri != null) {
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .border(1.5.dp, DarkInk.copy(alpha = 0.3f), RoundedCornerShape(8.dp))
                                .clip(RoundedCornerShape(8.dp))
                                .background(PinkVivid.copy(alpha = 0.08f))
                                .padding(horizontal = 12.dp, vertical = 8.dp)
                        ) {
                            Row(
                                verticalAlignment   = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                Icon(
                                    if (attachType == "PDF") Icons.Default.PictureAsPdf
                                    else Icons.Default.Image,
                                    contentDescription = null,
                                    modifier = Modifier.size(18.dp),
                                    tint     = PinkVivid
                                )
                                Text(
                                    text     = attachName ?: "arquivo",
                                    style    = MaterialTheme.typography.bodySmall,
                                    color    = DarkInk,
                                    modifier = Modifier.weight(1f),
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis
                                )
                                Box(
                                    modifier = Modifier
                                        .size(20.dp)
                                        .clip(RoundedCornerShape(4.dp))
                                        .clickable {
                                            attachType = null
                                            attachUri  = null
                                            attachName = null
                                        },
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        Icons.Default.Close, "Remover",
                                        modifier = Modifier.size(14.dp),
                                        tint     = DarkInk.copy(alpha = 0.6f)
                                    )
                                }
                            }
                        }
                    }

                    // Campo de link
                    if (attachType == "LINK") {
                        TextField(
                            value         = linkUrl,
                            onValueChange = { linkUrl = it },
                            placeholder   = {
                                Text(
                                    "URL (https://...)",
                                    color = DarkInk.copy(alpha = 0.38f),
                                    style = MaterialTheme.typography.bodyMedium
                                )
                            },
                            leadingIcon = {
                                Icon(Icons.Default.Link, null,
                                    modifier = Modifier.size(18.dp), tint = PinkVivid)
                            },
                            trailingIcon = if (linkUrl.isNotEmpty()) ({
                                Box(
                                    modifier = Modifier
                                        .size(24.dp)
                                        .clip(RoundedCornerShape(4.dp))
                                        .clickable { attachType = null; linkUrl = "" },
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(Icons.Default.Close, "Limpar",
                                        modifier = Modifier.size(16.dp),
                                        tint = DarkInk.copy(alpha = 0.6f))
                                }
                            }) else null,
                            singleLine = true,
                            modifier   = Modifier
                                .fillMaxWidth()
                                .border(2.dp, PinkVivid.copy(alpha = 0.5f), RoundedCornerShape(8.dp)),
                            shape  = RoundedCornerShape(8.dp),
                            colors = styledTextFieldColors()
                        )
                    }

                    // ── Botão Adicionar ────────────────────────────────────
                    val active = title.isNotBlank()
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .graphicsLayer { clip = false }
                            .drawBehind {
                                drawRoundRect(
                                    color        = DarkInk.copy(alpha = if (active) 1f else 0.4f),
                                    topLeft      = Offset(4.dp.toPx(), 4.dp.toPx()),
                                    size         = size,
                                    cornerRadius = CornerRadius(8.dp.toPx())
                                )
                            }
                    ) {
                        Button(
                            onClick = {
                                if (title.isBlank()) { titleError = true; return@Button }
                                val finalUri = when (attachType) {
                                    "LINK" -> linkUrl.trim().ifBlank { null }
                                    else   -> attachUri
                                }
                                val finalName = when (attachType) {
                                    "LINK" -> linkUrl.trim().ifBlank { null }
                                    else   -> attachName
                                }
                                onConfirm(
                                    title.trim(), description.trim(),
                                    finalUri, if (finalUri != null) attachType else null,
                                    finalName
                                )
                            },
                            modifier = Modifier.fillMaxWidth(),
                            shape    = RoundedCornerShape(8.dp),
                            enabled  = active,
                            border   = BorderStroke(2.dp, DarkInk.copy(alpha = if (active) 1f else 0.4f)),
                            colors   = ButtonDefaults.buttonColors(
                                containerColor         = PinkVivid,
                                disabledContainerColor = PinkVivid.copy(alpha = 0.5f)
                            ),
                            contentPadding = PaddingValues(vertical = 14.dp)
                        ) {
                            Text(
                                "Adicionar",
                                fontWeight    = FontWeight.ExtraBold,
                                color         = Color.White,
                                letterSpacing = 1.sp
                            )
                        }
                    }
                }
            }
        }
    }
}

// ── Botão de anexo estilizado ─────────────────────────────────────────────────
@Composable
private fun TaskAttachButton(
    icon: ImageVector,
    label: String,
    selected: Boolean,
    modifier: Modifier = Modifier,
    onClick: () -> Unit
) {
    Box(
        modifier = modifier
            .graphicsLayer { clip = false }
            .drawBehind {
                if (selected) {
                    drawRoundRect(
                        color        = DarkInk,
                        topLeft      = Offset(3.dp.toPx(), 3.dp.toPx()),
                        size         = size,
                        cornerRadius = CornerRadius(8.dp.toPx())
                    )
                }
            }
    ) {
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .border(
                    width  = if (selected) 2.dp else 1.5.dp,
                    color  = if (selected) DarkInk else DarkInk.copy(alpha = 0.25f),
                    shape  = RoundedCornerShape(8.dp)
                )
                .clip(RoundedCornerShape(8.dp))
                .background(if (selected) PinkVivid else Cream)
                .clickable { onClick() }
                .padding(vertical = 8.dp),
            contentAlignment = Alignment.Center
        ) {
            Column(
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(3.dp)
            ) {
                Icon(
                    icon, null,
                    modifier = Modifier.size(18.dp),
                    tint     = if (selected) Color.White else DarkInk.copy(alpha = 0.6f)
                )
                Text(
                    label,
                    style      = MaterialTheme.typography.labelSmall,
                    fontWeight = if (selected) FontWeight.Bold else FontWeight.Normal,
                    color      = if (selected) Color.White else DarkInk.copy(alpha = 0.6f)
                )
            }
        }
    }
}

// ── Helpers ───────────────────────────────────────────────────────────────────
private fun grantPersistablePermission(context: Context, uri: Uri) {
    try {
        context.contentResolver.takePersistableUriPermission(
            uri, android.content.Intent.FLAG_GRANT_READ_URI_PERMISSION
        )
    } catch (_: Exception) {}
}

private fun getFileName(context: Context, uri: Uri): String {
    var result: String? = null
    if (uri.scheme == "content") {
        context.contentResolver.query(uri, null, null, null, null)?.use { cursor ->
            if (cursor.moveToFirst()) {
                val idx = cursor.getColumnIndex(OpenableColumns.DISPLAY_NAME)
                if (idx >= 0) result = cursor.getString(idx)
            }
        }
    }
    return result ?: uri.lastPathSegment ?: "arquivo"
}

